('reasoning','fixed','{"questions":[{"id":"repeat","topic":"Patterns","prompt":"This three-shape unit repeats: circle, square, triangle. Which shape comes next?","visual":["●","■","▲","●","■","?"],"options":["Circle","Square","Triangle","Diamond"],"answer":2,"explanation":"The unit is circle, square, triangle. Two complete units end with a triangle.","lesson":"spotting-repeating-patterns"},{"id":"jump","topic":"Numbers","prompt":"The rule is “add 3 each time”. Which number replaces the question mark?","visual":["2","5","8","11","?"],"options":["12","13","15","14"],"answer":3,"explanation":"Every jump is three. Add three to eleven to get fourteen.","lesson":"number-patterns-check-every-step"},{"id":"turn","topic":"Space","prompt":"An arrow points up. Turn it one quarter-turn clockwise. Where does it point?","visual":["↑","↻","?"],"options":["Right","Left","Down","Up"],"answer":0,"explanation":"Clockwise from up is right after one quarter-turn. Down would need two quarter-turns.","lesson":"rotation-or-reflection"},{"id":"both","topic":"Logic","prompt":"Choose the object that is both red AND round.","options":["Red square","Blue circle","Red circle","Blue square"],"answer":2,"explanation":"Both properties must hold for the same object. A red square misses “round”; a blue circle misses “red”.","lesson":"sorting-with-two-rules"},{"id":"alternate","topic":"Patterns","prompt":"Starting at 1, alternate adding 2 and adding 5. What comes next?","visual":["1","3","8","10","15","?"],"options":["20","17","18","30"],"answer":1,"explanation":"The jumps are +2, +5, +2, +5. The next jump is +2, giving seventeen.","lesson":"number-patterns-check-every-step"},{"id":"week","topic":"Numbers","prompt":"Today is Tuesday. What weekday will it be after 10 days have passed?","options":["Thursday","Saturday","Friday","Sunday"],"answer":2,"explanation":"Seven days later is Tuesday again. Three more days take you through Wednesday and Thursday to Friday. Today is day zero.","lesson":"days-months-and-years"},{"id":"mirror","topic":"Space","prompt":"A dot is in the top-right corner of a square. Reflect it across a horizontal line through the square’s centre. Where is the dot now?","options":["Top-left","Top-right","Bottom-left","Bottom-right"],"answer":3,"explanation":"A horizontal mirror line swaps top and bottom. It does not swap left and right, so the dot moves to bottom-right.","lesson":"rotation-or-reflection"},{"id":"all","topic":"Logic","prompt":"Every triangle in a collection has dots. This shape has no dots. What must be true?","options":["It is a square","It is not a triangle","It is a red circle","It has three sides"],"answer":1,"explanation":"A triangle would have dots according to the rule. With no dots, this shape cannot be a triangle. The rule does not tell us its actual shape or colour.","lesson":"logic-what-must-be-true"},{"id":"two-step","topic":"Patterns","prompt":"The rule is “double the previous number, then add 1”. Which term comes next?","visual":["2","5","11","23","?"],"options":["47","46","48","35"],"answer":0,"explanation":"Double twenty-three to get forty-six, then add one. The same two steps also produce each earlier term.","lesson":"number-patterns-check-every-step"},{"id":"grid","topic":"Numbers","prompt":"In every row, the first two numbers add up to the third. Complete the bottom row.","grid":[["2","3","5"],["4","5","9"],["6","7","?"]],"options":["11","12","14","13"],"answer":3,"explanation":"Read across each row: 2 + 3 = 5, 4 + 5 = 9, and 6 + 7 = 13. The stated rule applies independently to each row.","lesson":"addition-putting-things-together"},{"id":"turn-flip","topic":"Space","prompt":"An arrow points right. Turn it a quarter-turn clockwise, then reflect it across a horizontal mirror line. Where does it finish?","visual":["→","↻","↕","?"],"options":["Right","Down","Up","Left"],"answer":2,"explanation":"The clockwise turn changes right to down. Reflecting across a horizontal line changes down to up. Apply the operations in the given order.","lesson":"rotation-or-reflection"},{"id":"two-rules","topic":"Logic","prompt":"A two-digit code has digits that add to 9. The second digit is larger than the first. Which code fits BOTH clues?","options":["63","27","28","44"],"answer":1,"explanation":"2 + 7 = 9 and 7 is larger than 2. In 63 the sum works but the order fails. The digits in 28 and 44 do not add to nine.","lesson":"sorting-with-two-rules"}]}'::jsonb);
