-- Immutable, private question snapshots. Sharing never writes a game result.
create schema if not exists brainilab_replay_private;
revoke all on schema brainilab_replay_private from public, anon, authenticated;
create table brainilab_replay_private.catalog(family text not null, key text not null, payload jsonb not null, primary key(family,key));
create table brainilab_replay_private.packs(
 id uuid primary key default gen_random_uuid(), game_id text not null,
 payload jsonb not null, answers jsonb not null, created_by uuid not null,
 fingerprint text not null, created_at timestamptz not null default now(),
 expires_at timestamptz not null default now()+interval '90 days'
);
create index on brainilab_replay_private.packs(created_by,created_at);
create index on brainilab_replay_private.packs(game_id,fingerprint);
alter table brainilab_replay_private.catalog enable row level security;
alter table brainilab_replay_private.packs enable row level security;
revoke all on all tables in schema brainilab_replay_private from public,anon,authenticated;

create function brainilab_replay_private.item(g text, src text, ref text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare r jsonb; a jsonb; rowdata record;
begin
 if src='local' then
  select payload into r from brainilab_replay_private.catalog where family=g and key=ref;
 elsif g='quiz' or g='survival' then
  select jsonb_build_object('q',v.prompt,'a',jsonb_agg(o.option_text order by o.position),'optionIds',jsonb_agg(o.id order by o.position),
   'questionVersionId',v.id,'cloudContent',true,'__answer',jsonb_build_object('id',max(o.id::text) filter(where o.is_correct),'text',max(o.option_text) filter(where o.is_correct),'explanation',v.explanation),
   'difficulty',v.difficulty,'topic',t.slug)
  into r from public.question_versions v join public.questions q on q.id=v.question_id
   join public.question_options o on o.question_version_id=v.id join public.topics t on t.id=v.primary_topic_id
  where v.id=ref::uuid and v.status='published' and q.status='active' group by v.id,t.slug;
  if g='survival' then r=(r-'questionVersionId'-'cloudContent')||jsonb_build_object('id',ref,'cloud',true);end if;
 elsif g='connections' then
  select jsonb_build_object('id',p.id,'externalKey',p.external_key,'category',p.category,'prompt',coalesce(p.prompt,'What connects these?'),'clues',p.clues,'source','supabase',
   'choices',jsonb_agg(jsonb_build_object('id',c.id,'text',c.choice_text) order by c.position),'__answer',jsonb_build_object('id',max(c.id::text) filter(where c.is_correct),'text',max(c.choice_text) filter(where c.is_correct),'explanation',p.explanation))
  into r from public.connections_puzzles p join public.connections_choices c on c.puzzle_id=p.id where p.id=ref::uuid and p.is_active group by p.id;
 elsif g='sequence' then
  select jsonb_build_object('id',id,'category',category,'sequence',sequence_values,'options',options,'cloud',true,'__answer',jsonb_build_object('answer',answer_value,'explanation',explanation)) into r from public.sequence_puzzles where id=ref::uuid and is_active;
 elsif g='oddoneout' then
  select jsonb_build_object('id',id,'category',category,'prompt',prompt,'items',items,'cloud',true,'__answer',jsonb_build_object('index',odd_index,'explanation',explanation)) into r from public.odd_one_out_puzzles where id=ref::uuid and is_active;
 elsif g='higherlower' then
  select jsonb_build_object('id',id,'category',category,'metric',metric,'comparisonType',comparison_type,'left',left_label,'leftValue',left_value,'right',right_label,'unit',coalesce(unit,''),'cloud',true,
   '__answer',jsonb_build_object('value',right_value,'direction',public.brainilab_higher_lower_direction(comparison_type,left_value,right_value),'label',public.brainilab_higher_lower_label(comparison_type,public.brainilab_higher_lower_direction(comparison_type,left_value,right_value)),'explanation',explanation)) into r from public.higher_lower_pairs where id=ref::uuid and is_active;
 elsif g='numberroute' then
  select jsonb_build_object('id',id,'category',category,'numbers',numbers,'target',target,'cloud',true,'__answer',jsonb_build_object('solution',solution)) into r from public.number_route_puzzles where id=ref::uuid and is_active;
 elsif g='orderup' then
  select jsonb_build_object('roundId',p.id,'title',p.title,'prompt',p.prompt,'directionLabel',p.direction_label,'items',jsonb_agg(jsonb_build_object('itemId',i.id,'label',i.label) order by i.sort_position),
   '__answer',jsonb_build_object('items',jsonb_agg(jsonb_build_object('item_id',i.id,'label',i.label) order by i.sort_position))) into r
  from public.order_up_rounds p join public.order_up_items i on i.round_id=p.id where p.id=ref::uuid and p.is_active group by p.id;
 elsif g='topicrush' then
  select jsonb_build_object('topicId',t.id,'title',t.title,'prompt',t.prompt,'targetCount',t.target_count,'durationSeconds',60,
   '__answer',jsonb_build_object('answers',jsonb_agg(jsonb_build_object('id',a.id,'answer',a.answer_text,'normalized',a.normalized_answer,'aliases',a.normalized_aliases)))) into r
  from public.topic_rush_topics t join public.topic_rush_answers a on a.topic_id=t.id where t.id=ref::uuid and t.is_active group by t.id;
 elsif g='brainiword' then
  select jsonb_build_object('contentRef',id,'letters',5,'attempts',5,'__answer',jsonb_build_object('word',upper(word))) into r from public.brainiword_words where id=ref::uuid and is_active;
 end if;
 if r is null then raise exception 'The original question is no longer available.';end if;
 return r;
end $$;

create function brainilab_replay_private.create_pack(g text, spec jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare actor uuid:=auth.uid(); src text:=spec->>'source'; fam text; ref text; r jsonb; visible jsonb; answers jsonb:='{}'; rows jsonb:='[]';
 payload jsonb; ids jsonb:=spec->'ids'; choices jsonb; original jsonb; ordered jsonb; i int:=0; j int; key text; n int; found uuid; fp text; meta jsonb:=coalesce(spec->'meta','{}');
begin
 if actor is null then raise exception 'Please retry the invitation.';end if;
 if g is null or src is null or g not in ('brainmix','worldflags','worldcapitals','generalknowledge','science','history','sports','survival','connections','sequence','oddoneout','higherlower','numberroute','mathrush','orderup','topicrush','brainiword','reasoning') or src not in ('local','supabase') or octet_length(spec::text)>24000 then raise exception 'Invalid challenge.';end if;
 if jsonb_typeof(ids)<>'array' or jsonb_array_length(ids)>60 then raise exception 'Invalid question set.';end if;
 -- Metadata is allowlisted; callers cannot put private profile data or arbitrary prose in a shared pack.
 if exists(select 1 from jsonb_object_keys(meta) k where k not in ('dailyChallengeId','challengeDate','dailyNumber','generationVersion','totalQuestions','topicKey','topicSlug','topicId','difficulty','setNumber','version','selectionMode','totalRounds','itemsPerRound'))
  or octet_length(meta::text)>1300 then raise exception 'Invalid challenge settings.';end if;
 if meta ? 'challengeDate' and meta->>'challengeDate' is not null and (meta->>'challengeDate'!~'^20[0-9]{2}-[0-9]{2}-[0-9]{2}$' or (meta->>'challengeDate')::date>current_date) then raise exception 'Invalid challenge date.';end if;
 perform pg_advisory_xact_lock(hashtextextended('friend-pack:'||actor::text,0));
 fam=case when g in ('brainmix','worldflags','worldcapitals','generalknowledge','science','history','sports') then 'quiz' else g end;
 if jsonb_typeof(spec->'settings')<>'object' or octet_length((spec->'settings')::text)>200 or (spec->'settings'->>'rounds')::int not between 1 and 60 then raise exception 'Invalid challenge rules.';end if;
 payload=meta||jsonb_build_object('source',src,'replayRules','friend-replay-v1','friendSettings',spec->'settings');
 if g='mathrush' then
  if spec->>'seed'!~'^v2:(daily:[0-9-]{10}:mathrush|anytime:[A-Za-z0-9-]{10,64})$' then raise exception 'Invalid maths challenge.';end if;
  r=public.get_brainilab_math_rush_game(spec->>'seed',null);
  select jsonb_agg(jsonb_build_object('id',coalesce(x->>'operation_id',(r->>'seed')||':'||(x->>'position')),'position',(x->>'position')::int,'a',(x->>'a')::numeric,'b',(x->>'b')::numeric,'op',x->>'operator',
   'answer',case x->>'operator' when '+' then (x->>'a')::numeric+(x->>'b')::numeric when '−' then (x->>'a')::numeric-(x->>'b')::numeric when '×' then (x->>'a')::numeric*(x->>'b')::numeric else (x->>'a')::numeric/(x->>'b')::numeric end,
   'display',(x->>'a')||' '||(x->>'operator')||' '||(x->>'b')) order by (x->>'position')::int) into rows from jsonb_array_elements(r->'operations') x;
  payload=payload||jsonb_build_object('seed',r->>'seed','operations',rows);
 elsif g in ('topicrush','brainiword','reasoning') then
  ref=case g when 'topicrush' then spec->>'topicId' when 'brainiword' then spec->>'wordId' else 'fixed' end;
  r=brainilab_replay_private.item(fam,src,ref);payload=payload||(r-'__answer');answers=jsonb_build_object(ref,r->'__answer');
 else
  n=jsonb_array_length(ids);
  if not (case when fam='quiz' then n=case when g='brainmix' then 10 else 20 end when g='survival' then n between 15 and 30 when g='connections' then n in (3,20) when g='numberroute' then n in (3,10) when g='orderup' then n=2 else n=10 end) then raise exception 'Incomplete question set.';end if;
  if (select count(distinct x) from jsonb_array_elements_text(ids) x)<>n then raise exception 'Repeated question references.';end if;
  for ref in select jsonb_array_elements_text(ids) loop
   r=brainilab_replay_private.item(fam,src,ref);visible=r-'__answer';choices=spec->'choices'->i;
   if fam='quiz' or g='survival' then
    if src='supabase' then
     original=r->'optionIds';
     if jsonb_array_length(choices)<>4 or not (choices @> original and original @> choices) then raise exception 'Changed answer options.';end if;
     ordered='[]';for key in select jsonb_array_elements_text(choices) loop j=0;while original->>j<>key loop j=j+1;end loop;ordered=ordered||jsonb_build_array(r->'a'->j);end loop;
     visible=visible||jsonb_build_object('a',ordered,'optionIds',choices);
    end if;
   elsif g in ('connections','orderup') then
    original=case g when 'connections' then r->'choices' else r->'items' end;key=case g when 'connections' then 'id' else 'itemId' end;
    if jsonb_array_length(choices)<>jsonb_array_length(original) or exists(select 1 from jsonb_array_elements_text(choices) v where not exists(select 1 from jsonb_array_elements(original) x where x->>key=v)) or (select count(distinct v) from jsonb_array_elements_text(choices) v)<>jsonb_array_length(original) then raise exception 'Changed answer options.';end if;
    select jsonb_agg(x order by c.ord) into ordered from jsonb_array_elements_text(choices) with ordinality c(id,ord) join jsonb_array_elements(original) x on x->>key=c.id;
    visible=visible||jsonb_build_object(case g when 'connections' then 'choices' else 'items' end,ordered);
    if g='orderup' then visible=visible||jsonb_build_object('position',i+1);end if;
   elsif g='sequence' then
    original=r->'options';if jsonb_array_length(choices)<>jsonb_array_length(original) or not(choices @> original and original @> choices) or (select count(distinct v) from jsonb_array_elements(choices) v)<>jsonb_array_length(original) then raise exception 'Changed answer options.';end if;
    visible=visible||jsonb_build_object('options',choices);
   end if;
   rows=rows||jsonb_build_array(visible);answers=answers||jsonb_build_object(ref,r->'__answer');i=i+1;
  end loop;
  payload=payload||jsonb_build_object(case when fam='quiz' or g='survival' then 'questions' else 'rounds' end,rows);
 end if;
 fp=md5(jsonb_build_array(g,payload,answers)::text);
 select id into found from brainilab_replay_private.packs where game_id=g and fingerprint=fp and expires_at>now() order by created_at limit 1;
 if found is null then
  if (select count(*) from brainilab_replay_private.packs where created_by=actor and created_at>now()-interval '1 day')>=50 then raise exception 'Please try another invitation tomorrow.';end if;
 end if;
 return jsonb_build_object('id',found,'gameId',g,'payload',payload);
end $$;

create function brainilab_replay_private.get_pack(pack uuid, g text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare result jsonb;
begin
 if auth.uid() is null then raise exception 'Please retry the invitation.';end if;
 select jsonb_build_object('id',id,'gameId',game_id,'payload',payload) into result from brainilab_replay_private.packs where id=pack and game_id=g and expires_at>now();
 if result is null then raise exception 'This invitation has expired. Ask your friend for a new one.';end if;
 return result;
end $$;

create function brainilab_replay_private.check_pack(pack uuid, method text, args jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare p brainilab_replay_private.packs%rowtype; a jsonb; r jsonb; ref text; selected text; correct bool; items jsonb; i int; j int; pairs int:=0; exact int:=0; value numeric; op text; guess text; word text; states jsonb; used boolean[]; letters text[]; attempt int; normalized text;
begin
 if auth.uid() is null or octet_length(args::text)>4000 then raise exception 'Invalid answer.';end if;
 select * into p from brainilab_replay_private.packs where id=pack and expires_at>now();if not found then raise exception 'This invitation is unavailable.';end if;
 ref=coalesce(args->>'p_question_version_id',args->>'p_puzzle_id',args->>'p_pair_id',args->>'p_round_id',p.payload->>'topicId',p.payload->>'contentRef');
 a=p.answers->ref;
 if p.payload->>'source'<>'supabase' or a is null then raise exception 'Invalid question reference.';end if;
 if method='check_brainilab_quiz_answer' and p.game_id in ('brainmix','worldflags','worldcapitals','generalknowledge','science','history','sports','survival') then
  select x into r from jsonb_array_elements(p.payload->'questions') x where coalesce(x->>'questionVersionId',x->>'id')=ref;
  selected=args->>'p_selected_option_id';if selected is not null and not((r->'optionIds') ? selected) then raise exception 'Invalid option.';end if;
  select r->'a'->>(ord-1)::int into word from jsonb_array_elements_text(r->'optionIds') with ordinality o(id,ord) where id=selected;
  return jsonb_build_object('is_correct',coalesce(selected=a->>'id',false),'correct_option_id',a->>'id','correct_answer',a->>'text','selected_answer',word,'explanation',a->>'explanation');
 elsif method='check_brainilab_connections_guess' and p.game_id='connections' then
  selected=args->>'p_choice_id';if not exists(select 1 from jsonb_array_elements(p.payload->'rounds') z cross join jsonb_array_elements(z->'choices') c where z->>'id'=ref and c->>'id'=selected) then raise exception 'Invalid option.';end if;
  return jsonb_build_object('correct',selected=a->>'id','correct_choice_id',a->>'id','answer',a->>'text','explanation',a->>'explanation');
 elsif method='check_brainilab_sequence_answer' and p.game_id='sequence' then
  return jsonb_build_object('correct',(args->>'p_answer')::numeric=(a->>'answer')::numeric,'answer',a->'answer','explanation',a->>'explanation');
 elsif method='check_brainilab_odd_one_out_answer' and p.game_id='oddoneout' then
  return jsonb_build_object('correct',(args->>'p_item_index')::int=(a->>'index')::int,'correct_index',a->'index','explanation',a->>'explanation');
 elsif method='check_brainilab_higher_lower_answer' and p.game_id='higherlower' then
  return jsonb_build_object('correct',args->>'p_choice'=a->>'direction','direction',a->>'direction','label',a->>'label','right_value',a->'value','explanation',a->>'explanation');
 elsif method in ('check_brainilab_number_route_answer','reveal_brainilab_number_route_solution') and p.game_id='numberroute' then
  if method like 'reveal%' then return jsonb_build_object('solution',a->'solution');end if;
  select x into r from jsonb_array_elements(p.payload->'rounds') x where x->>'id'=ref;
  if jsonb_array_length(args->'p_operators')<>jsonb_array_length(r->'numbers')-1 then raise exception 'Invalid calculation.';end if;
  correct=args->'p_operators'=a->'solution';
  return jsonb_build_object('correct',correct,'target',r->'target','solution',case when correct then a->'solution' else null end);
 elsif method='check_brainilab_order_up_round' and p.game_id='orderup' then
  items=a->'items';
  if jsonb_array_length(args->'p_item_ids')<>10 or (select count(distinct x) from jsonb_array_elements_text(args->'p_item_ids') x)<>10 or exists(select 1 from jsonb_array_elements_text(args->'p_item_ids') x where not exists(select 1 from jsonb_array_elements(items) item where item->>'item_id'=x)) then raise exception 'Invalid order.';end if;
  for i in 0..9 loop if args->'p_item_ids'->>i=items->i->>'item_id' then exact=exact+1;end if;for j in i+1..9 loop if (select ord from jsonb_array_elements(items) with ordinality x(item,ord) where item->>'item_id'=args->'p_item_ids'->>i)<(select ord from jsonb_array_elements(items) with ordinality x(item,ord) where item->>'item_id'=args->'p_item_ids'->>j) then pairs=pairs+1;end if;end loop;end loop;
  return jsonb_build_object('correct_pairs',pairs,'total_pairs',45,'score',round(pairs::numeric/45*1250),'exact_positions',exact,'accuracy',round(pairs::numeric/45*100,2),'correct_order',items);
 elsif method='check_brainilab_topic_rush_answer' and p.game_id='topicrush' then
  normalized=public.brainilab_normalize_topic_rush_answer(args->>'p_guess');if length(normalized)<2 then return jsonb_build_object('valid',false,'reason','too_short');end if;
  select x into r from jsonb_array_elements(a->'answers') x where x->>'normalized'=normalized or (x->'aliases') ? normalized limit 1;
  return case when r is null then jsonb_build_object('valid',false,'reason','not_in_list') else jsonb_build_object('valid',true,'answer_id',r->>'id','canonical_answer',r->>'answer') end;
 elsif method='check_brainilab_brainiword_guess' and p.game_id='brainiword' then
  guess=upper(trim(args->>'p_guess'));attempt=(args->>'p_attempt')::int;word=a->>'word';
  if guess!~'^[A-Z]{5}$' or attempt not between 1 and 5 or not public.is_brainilab_english_guess(guess) then return jsonb_build_object('valid_word',false,'states','[]'::jsonb,'won',false,'finished',false);end if;
  used=array_fill(false,array[5]);letters=array_fill('absent'::text,array[5]);
  for i in 1..5 loop if substr(guess,i,1)=substr(word,i,1) then letters[i]='correct';used[i]=true;end if;end loop;
  for i in 1..5 loop if letters[i]='absent' then for j in 1..5 loop if not used[j] and substr(guess,i,1)=substr(word,j,1) then letters[i]='present';used[j]=true;exit;end if;end loop;end if;end loop;
  return jsonb_build_object('valid_word',true,'states',to_jsonb(letters),'won',guess=word,'finished',guess=word or attempt=5,'answer',case when guess=word or attempt=5 then word else null end);
 end if;
 raise exception 'Invalid answer checker.';
end $$;

create function public.create_brainilab_friend_pack(p_game_id text,p_spec jsonb) returns jsonb language sql security invoker set search_path='' as $$select brainilab_replay_private.create_pack(p_game_id,p_spec)$$;
create function public.get_brainilab_friend_pack(p_pack_id uuid,p_game_id text) returns jsonb language sql security invoker set search_path='' as $$select brainilab_replay_private.get_pack(p_pack_id,p_game_id)$$;
create function public.check_brainilab_friend_pack(p_pack_id uuid,p_method text,p_args jsonb) returns jsonb language sql security invoker set search_path='' as $$select brainilab_replay_private.check_pack(p_pack_id,p_method,p_args)$$;
revoke all on all functions in schema brainilab_replay_private from public,anon,authenticated;
grant usage on schema brainilab_replay_private to authenticated;
grant execute on function brainilab_replay_private.create_pack(text,jsonb),brainilab_replay_private.get_pack(uuid,text),brainilab_replay_private.check_pack(uuid,text,jsonb) to authenticated;
revoke all on function public.create_brainilab_friend_pack(text,jsonb),public.get_brainilab_friend_pack(uuid,text),public.check_brainilab_friend_pack(uuid,text,jsonb) from public,anon;
grant execute on function public.create_brainilab_friend_pack(text,jsonb),public.get_brainilab_friend_pack(uuid,text),public.check_brainilab_friend_pack(uuid,text,jsonb) to authenticated;

-- Canonical local fallback content already shipped in the public game bundles.
